return [{ json: {
  generatedAt: new Date().toISOString(),
  updates: [
    {jobId:'JOB-104', customer:'Anderson Residence', status:'painting-in-progress', lastActivity:'2026-09-09T15:30:00Z', note:'Crew completed first coat in living room; returning tomorrow for trim.'},
    {jobId:'JOB-118', customer:'Rivera Office', status:'stalled', lastActivity:'2026-09-08T10:00:00Z', note:'Waiting on stain-blocking primer; supplier delivery not confirmed.'},
    {jobId:'JOB-121', customer:'Miller Residence', status:'weather-delay', lastActivity:'2026-09-09T13:00:00Z', note:'Exterior work paused due to rain; customer notified.'},
    {jobId:'JOB-127', customer:'Green Kitchen', status:'customer-issue', lastActivity:'2026-09-09T16:15:00Z', note:'Customer requested a color change after sample approval; scope may change.'},
    {jobId:'JOB-130', customer:'Hill Property', status:'safety', lastActivity:'2026-09-09T14:00:00Z', note:'Crew reported unstable ladder setup; work stopped pending supervisor review.'}
  ]
}}];

const body = $json.body ?? $json;
const updates = body.updates ?? (Array.isArray(body) ? body : []);
const now = Date.now();
const normalized = updates.map(u => ({
  jobId: u.jobId ?? 'UNKNOWN',
  customer: u.customer ?? 'Unknown Customer',
  status: String(u.status ?? '').trim().toLowerCase(),
  lastActivity: u.lastActivity ?? null,
  note: String(u.note ?? '').trim(),
  hoursSinceActivity: u.lastActivity ? Math.round(((now - new Date(u.lastActivity).getTime())/3600000)*10)/10 : null
}));
return [{json:{generatedAt: body.generatedAt ?? new Date().toISOString(), updates: normalized}}];

const raw =
  $json.output ??
  $json.message?.content ??
  $json.text ??
  $json;

let text = String(raw).trim();

// Remove markdown code fences if the model added them
text = text
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

// Extract the JSON object
const start = text.indexOf('{');
const end = text.lastIndexOf('}');

if (start === -1 || end === -1 || end <= start) {
  throw new Error('AI response does not contain a JSON object.');
}

text = text.slice(start, end + 1);

let report;

try {
  report = JSON.parse(text);
} catch (error) {
  throw new Error(
    'AI returned invalid JSON: ' + error.message
  );
}

// Required fields
const required = [
  'summary',
  'jobsMoved',
  'stalledJobs',
  'needsAttention',
  'escalationItems',
  'metrics'
];

for (const key of required) {
  if (!(key in report)) {
    throw new Error('Missing report field: ' + key);
  }
}

// Ensure arrays
report.jobsMoved = Array.isArray(report.jobsMoved)
  ? report.jobsMoved
  : [];

report.stalledJobs = Array.isArray(report.stalledJobs)
  ? report.stalledJobs
  : [];

report.needsAttention = Array.isArray(report.needsAttention)
  ? report.needsAttention
  : [];

report.escalationItems = Array.isArray(report.escalationItems)
  ? report.escalationItems
  : [];

// Get original normalized source data
const source =
  $('Normalize & Filter Updates').item.json;

const updates = Array.isArray(source.updates)
  ? source.updates
  : [];

// Map original jobs
const jobMap = {};

for (const job of updates) {
  if (job.jobId) {
    jobMap[job.jobId] = job;
  }
}

// Primary classification priority
const categories = [
  'escalationItems',
  'stalledJobs',
  'needsAttention',
  'jobsMoved'
];

// Prevent duplicates
const assigned = new Set();

for (const category of categories) {
  const uniqueItems = [];

  for (const item of report[category]) {
    if (!item || !item.jobId) {
      continue;
    }

    const jobId = item.jobId;

    // Skip duplicate classifications
    if (assigned.has(jobId)) {
      continue;
    }

    const original = jobMap[jobId] || {};

    uniqueItems.push({
      ...item,
      jobId,
      customer:
        original.customer ??
        item.customer ??
        'Unknown Customer',
      hoursSinceActivity:
        original.hoursSinceActivity ??
        item.hoursSinceActivity ??
        null
    });

    assigned.add(jobId);
  }

  report[category] = uniqueItems;
}

// Fill fields from original source data

for (const item of report.jobsMoved) {
  const original = jobMap[item.jobId] || {};

  item.customer =
    original.customer ??
    item.customer ??
    'Unknown Customer';

  item.update =
    item.update ??
    original.note ??
    'No update';

  item.hoursSinceActivity =
    original.hoursSinceActivity ??
    item.hoursSinceActivity ??
    null;
}

for (const item of report.stalledJobs) {
  const original = jobMap[item.jobId] || {};

  item.customer =
    original.customer ??
    item.customer ??
    'Unknown Customer';

  item.reason =
    item.reason ??
    original.note ??
    'No reason provided';

  item.hoursSinceActivity =
    original.hoursSinceActivity ??
    item.hoursSinceActivity ??
    null;
}

for (const item of report.needsAttention) {
  const original = jobMap[item.jobId] || {};

  item.customer =
    original.customer ??
    item.customer ??
    'Unknown Customer';

  item.reason =
    item.reason ??
    original.note ??
    'No reason provided';

  item.recommendedAction =
    item.recommendedAction ??
    'Review required';
}

for (const item of report.escalationItems) {
  const original = jobMap[item.jobId] || {};

  item.customer =
    original.customer ??
    item.customer ??
    'Unknown Customer';

  item.reason =
    item.reason ??
    original.note ??
    'No reason provided';

  item.recommendedAction =
    item.recommendedAction ??
    'Immediate Project Manager review required';

  item.priority =
    item.priority ??
    'HIGH';

  item.hoursSinceActivity =
    original.hoursSinceActivity ??
    item.hoursSinceActivity ??
    null;
}

// Recalculate metrics from actual final classifications
report.metrics = {
  jobsReviewed: updates.length,
  jobsMoved: report.jobsMoved.length,
  stalled: report.stalledJobs.length,
  needsAttention: report.needsAttention.length,
  escalations: report.escalationItems.length
};

// Build readable report
const lines = [];

lines.push('# Painting Operations Morning Report');
lines.push('');
lines.push(
  'Summary: ' +
  (report.summary || 'No summary provided.')
);

lines.push('');
lines.push(
  'Metrics: ' +
  report.metrics.jobsReviewed +
  ' jobs reviewed | ' +
  report.metrics.jobsMoved +
  ' moved | ' +
  report.metrics.stalled +
  ' stalled | ' +
  report.metrics.needsAttention +
  ' attention | ' +
  report.metrics.escalations +
  ' escalations'
);

// Jobs moved
lines.push('');
lines.push('## 1) Jobs Moved');

if (report.jobsMoved.length === 0) {
  lines.push('- None reported');
} else {
  for (const item of report.jobsMoved) {
    lines.push(
      '- ' +
      item.jobId +
      ' - ' +
      item.customer +
      ': ' +
      item.update
    );
  }
}

// Stalled
lines.push('');
lines.push('## 2) Stalled Jobs');

if (report.stalledJobs.length === 0) {
  lines.push('- None');
} else {
  for (const item of report.stalledJobs) {
    lines.push(
      '- ' +
      item.jobId +
      ' - ' +
      item.customer +
      ': ' +
      item.reason +
      ' (' +
      (item.hoursSinceActivity ?? '?') +
      'h)'
    );
  }
}

// Attention
lines.push('');
lines.push('## 3) Needs Attention');

if (report.needsAttention.length === 0) {
  lines.push('- None');
} else {
  for (const item of report.needsAttention) {
    lines.push(
      '- ' +
      item.jobId +
      ' - ' +
      item.customer +
      ': ' +
      item.reason +
      ' | Action: ' +
      item.recommendedAction
    );
  }
}

// Escalations
lines.push('');
lines.push('## 4) Escalation Items');

if (report.escalationItems.length === 0) {
  lines.push('- None');
} else {
  for (const item of report.escalationItems) {
    lines.push(
      '- [' +
      item.priority +
      '] ' +
      item.jobId +
      ' - ' +
      item.customer +
      ': ' +
      item.reason +
      ' | Action: ' +
      item.recommendedAction
    );
  }
}

return [
  {
    json: {
      report,
      formattedReport: lines.join('\n'),
      generatedAt: new Date().toISOString()
    }
  }
];

const source = $('Validate & Format Report').item.json;
const report = source.report;

return [{
  json: {
    status: 'AUDITED',
    loggedAt: new Date().toISOString(),
    generatedAt: source.generatedAt,
    formattedReport: source.formattedReport,
    report,
    metrics: report.metrics,
    escalationTriggered: Number(report.metrics?.escalations ?? 0) > 0
  }
}];

